oxy_webhelp_navlinks = {"tocId-d39307e40690":{"topics":[{"title":"Key features for SAP HANA protection","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides automated backup management, flexible recovery options,         and advanced data protection features for SAP HANA databases running on on-premises         infrastructure and public cloud environments.<\/p>","href":"saas\/saphana_key_features_protection.html","attributes":{"data-id":"saphana_key_features_protection"},"menu":{"hasChildren":false},"tocID":"saphana_key_features_protection-d39307e40691","topics":[]},{"title":"SAP HANA databases","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enables administrators to implement backup policies on SAP HANA         databases running on public clouds and on-premises.<\/p>","href":"saas\/sap_hana_protection.html","attributes":{"data-id":"sap_hana_protection"},"menu":{"hasChildren":false},"tocID":"sap_hana_protection-d39307e40704","topics":[]},{"title":"Common SAP HANA protection terms","shortdesc":"<p class=\"shortdesc\">Information about common terms used when protecting SAP HANA databases with <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/saphana_common_protection_terms.html","attributes":{"data-id":"saphana_common_protection_terms"},"menu":{"hasChildren":false},"tocID":"saphana_common_protection_terms-d39307e40717","topics":[]},{"title":"SAP HANA protection architecture","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> integrates with SAP HANA through its native Backint client, which         is deployed automatically on the SAP HANA host when the RBS or an external tool is         deployed.<\/p>","href":"saas\/sap_hana_architecture.html","attributes":{"data-id":"sap_hana_architecture"},"menu":{"hasChildren":false},"tocID":"sap_hana_architecture-d39307e40731","topics":[]}]}};